"use client";

import { useId, useState, type ComponentProps } from "react";
import { Check } from "lucide-react";
import { cn } from "cn";
import { Badge } from "../components/badge";
import { Card } from "../components/card";
import { Button } from "../components/button";


interface PricingProps extends Omit<ComponentProps<"section">, "title"> {
  title?: string;
  description?: string;
  defaultBilling?: "monthly" | "yearly";
  plans?: {
    name: string;
    description: string;
    monthlyPrice: number;
    yearlyPrice: number;
    features: string[];
    href: string;
    label?: string;
    featured?: boolean;
  }[];
}

export function Pricing({ title = "A plan for every next step", description = "Start small. Make room as you grow.", defaultBilling = "monthly", plans = [{ name: "Starter", description: "For your next side project.", monthlyPrice: 0, yearlyPrice: 0, features: ["1 workspace", "Core components", "Community support"], href: "/signup", label: "Start for free" }, { name: "Pro", description: "For ideas ready to grow.", monthlyPrice: 19, yearlyPrice: 15, features: ["Unlimited workspaces", "All components and blocks", "Priority support"], href: "/signup?plan=pro", featured: true }, { name: "Team", description: "For building together.", monthlyPrice: 49, yearlyPrice: 39, features: ["Everything in Pro", "Team collaboration", "Dedicated support"], href: "/signup?plan=team" }], className, children, ...props }: PricingProps = {}) {
  const [billing, setBilling] = useState(defaultBilling);
  const id = useId();
  const actionClass = "inline-flex min-h-11 w-full items-center justify-center border border-border px-4 py-2 text-sm font-semibold focus-visible:outline-2 focus-visible:outline-ring";
  function price(plan: (typeof plans)[number]) { return billing === "yearly" ? plan.yearlyPrice : plan.monthlyPrice; }
  return (<section {...props} aria-labelledby={props["aria-labelledby"] ?? `${id}-title`} data-slot="pricing" data-layout="cards" className={cn("@container w-full space-y-8 text-foreground", className)}>
    <div className="text-center"><h2 id={`${id}-title`} className="text-3xl font-semibold tracking-tight">{title}</h2><p className="mt-3 text-sm text-muted-foreground">{description}</p></div>
    <div role="group" aria-label="Billing period" className="flex justify-center gap-1">
      <Button variant={billing === "monthly" ? "primary" : "secondary"} aria-pressed={billing === "monthly"} onClick={() => setBilling("monthly")}>Monthly</Button>
      <Button variant={billing === "yearly" ? "primary" : "secondary"} aria-pressed={billing === "yearly"} onClick={() => setBilling("yearly")}>Yearly</Button>
    </div>
    <p aria-live="polite" className="text-center text-xs text-muted-foreground">{billing === "yearly" ? "Monthly prices shown. Billed once a year." : "Billed monthly. Switch to yearly for lower monthly prices."}</p>
    {<div className={cn("grid gap-4", "@xl:grid-cols-3")}>
      {plans.map(plan => <Card key={plan.name} title="" description="" className={cn("max-w-none!", plan.featured && "border-primary")} footer={<a href={plan.href} aria-label={`${plan.label ?? "Get started"} with ${plan.name}`} className={cn(actionClass, plan.featured ? "bg-primary text-primary-foreground hover:bg-primary/90" : "hover:bg-muted")}>{plan.label ?? "Get started"}</a>}>
        <div>
          <div><div className="flex flex-wrap items-center gap-3"><h3 className="text-lg font-semibold">{plan.name}</h3>{plan.featured && <Badge variant="info">Popular</Badge>}</div><p className="mt-2 text-sm text-muted-foreground">{plan.description}</p><p className="mt-5"><span className="text-3xl font-semibold">${price(plan)}</span><span className="text-xs text-muted-foreground"> / month</span></p>{billing === "yearly" && <p className="mt-1 text-xs text-muted-foreground">${price(plan) * 12} billed yearly</p>}</div>
          <ul className="mt-6 space-y-3 text-sm">{plan.features.map(feature => <li key={feature} className="flex items-start gap-2"><Check size={16} aria-hidden="true" className="mt-0.5 shrink-0 text-primary" />{feature}</li>)}</ul>

        </div>
      </Card>)}
    </div>}
    {children}
  </section>);
}

import type { ComponentProps } from "react";

interface BadgeProps extends ComponentProps<"span"> {
  variant?: "neutral" | "info" | "success" | "warning" | "error" | "blue" | "purple" | "pink" | "teal" | "orange";
}

export function Badge({ children = "New release", variant = "success", className = "", ...props }: BadgeProps = {}) {
  const styles = {
    neutral: "bg-neutral-800 text-neutral-200",
    info: "bg-sky-400/10 text-sky-300",
    success: "bg-emerald-400/10 text-emerald-300",
    warning: "bg-amber-400/10 text-amber-300",
    error: "bg-red-400/10 text-red-300",
    blue: "bg-blue-400/10 text-blue-300",
    purple: "bg-purple-400/10 text-purple-300",
    pink: "bg-pink-400/10 text-pink-300",
    teal: "bg-teal-400/10 text-teal-300",
    orange: "bg-orange-400/10 text-orange-300",
  };
  return <span className={`inline-flex items-center border border-border px-2.5 py-1 text-xs font-medium ${styles[variant] ?? styles.success} ${className}`} {...props}>{children}</span>;
}

import type { ComponentProps } from "react";

interface ButtonProps extends ComponentProps<"button"> {
  variant?: "primary" | "secondary" | "ghost" | "destructive" | "outline";
}

export function Button({
  children = "Get started",
  variant = "primary",
  className = "",
  type = "button",
  ...props
}: ButtonProps = {}) {
  const styles = {
    primary: "bg-emerald-400 text-neutral-950 hover:bg-emerald-300",
    secondary: "bg-neutral-800 text-white hover:bg-neutral-700",
    ghost: "bg-transparent text-foreground hover:bg-muted",
    destructive: "bg-destructive text-destructive-foreground hover:bg-destructive/90",
    outline: "border border-border text-white hover:bg-neutral-800",
  };
  return (
    <button
      type={type}
      className={`inline-flex min-h-11 items-center justify-center gap-2 px-5 py-2 text-sm font-semibold transition-colors focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-emerald-400 disabled:pointer-events-none disabled:opacity-50 ${styles[variant] ?? styles.primary} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
}

import type { ComponentProps, ReactNode } from "react";

interface CardProps extends Omit<ComponentProps<"article">, "title"> {
  title?: string;
  description?: string;
  footer?: ReactNode;
}

export function Card({ title = "Room for your next idea", description = "A simple starting point for something great. Make it yours.", children, footer, className = "", ...props }: CardProps = {}) {
  return <article className={`w-full max-w-sm border border-border bg-card p-6 text-card-foreground shadow-sm ${className}`} {...props}>
    {title && <h3 className="text-lg font-semibold">{title}</h3>}
    {description && <p className="mt-2 text-sm leading-6 opacity-80">{description}</p>}
    {children && <div className={title || description || footer ? "mt-5" : "h-full min-h-0"}>{children}</div>}
    {footer && <footer className="mt-5 border-t border-border pt-4">{footer}</footer>}
  </article>;
}
